srcDoc.css:
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: #eef2f6;
  font-family: Arial, sans-serif;
  color: #17202a;
}

.print-actions {
  padding: 10px 14px;
  background: #17202a;
  display: flex;
  justify-content: flex-end;
}

.print-btn {
  border: 0;
  background: white;
  color: #17202a;
  font-weight: 800;
  font-size: 12px;
  padding: 8px 14px;
  border-radius: 4px;
  cursor: pointer;
}

.print-page {
  width: 210mm;
  min-height: 297mm;
  margin: 14px auto;
  padding: 18mm;
  background: white;
  box-shadow: 0 12px 30px rgba(16, 24, 40, 0.16);
}

.header {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 3px solid #17202a;
  padding-bottom: 16px;
}

.company {
  display: flex;
  gap: 14px;
}

.logo {
  width: 82px;
  height: 68px;
  object-fit: contain;
  border: 1px solid #e4e7ec;
  padding: 4px;
}

.company-name {
  font-size: 19px;
  font-weight: 800;
  margin-bottom: 5px;
}

.muted {
  color: #667085;
  font-size: 12px;
  line-height: 1.45;
}

.doc-title {
  text-align: right;
}

.doc-title h1 {
  margin: 0;
  font-size: 25px;
  letter-spacing: 0;
}

.doc-number {
  font-size: 18px;
  font-weight: 800;
  margin-top: 8px;
}

.status {
  display: inline-block;
  margin-top: 8px;
  padding: 5px 8px;
  background: #ecfdf3;
  color: #067647;
  font-size: 11px;
  font-weight: 800;
  border-radius: 4px;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 9px;
  margin: 18px 0;
}

.info-box {
  border: 1px solid #d0d5dd;
  padding: 9px;
  min-height: 58px;
}

.info-box span {
  display: block;
  color: #667085;
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 800;
  margin-bottom: 5px;
}

.info-box b {
  font-size: 13px;
}

.report-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 12px;
}

.report-table th {
  background: #17202a;
  color: white;
  padding: 8px;
  font-size: 10px;
  text-align: left;
}

.report-table td {
  border-bottom: 1px solid #e4e7ec;
  padding: 8px;
  font-size: 11px;
  vertical-align: top;
}

.right {
  text-align: right;
}

.center {
  text-align: center;
}

.product-code {
  font-weight: 800;
}

.small {
  color: #667085;
  font-size: 10px;
  margin-top: 2px;
}

.priority {
  display: inline-block;
  min-width: 58px;
  text-align: center;
  padding: 4px 6px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 900;
}

.priority.urgent {
  background: #fee4e2;
  color: #b42318;
}

.priority.low {
  background: #fff4e5;
  color: #b54708;
}

.priority.sales_demand {
  background: #eef4ff;
  color: #1849a9;
}

.priority.ok {
  background: #ecfdf3;
  color: #067647;
}

.check-cell {
  width: 28px;
  height: 22px;
  border: 1px solid #98a2b3;
  display: inline-block;
}

.summary {
  margin-left: auto;
  margin-top: 18px;
  width: 340px;
  border-collapse: collapse;
}

.summary td {
  border-bottom: 1px solid #e4e7ec;
  padding: 8px;
  font-size: 12px;
}

.signatures {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  margin-top: 56px;
}

.signature {
  border-top: 1px solid #17202a;
  text-align: center;
  padding-top: 7px;
  font-size: 12px;
}

@media print {
  body {
    background: white;
  }
  .print-actions {
    display: none;
  }
  .print-page {
    margin: 0;
    box-shadow: none;
    width: auto;
    min-height: auto;
  }
}

