function esc(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
}
function qty(value) {
  return Number(value || 0).toFixed(4);
}
function priorityClass(value) {
  return String(value || "OK").toLowerCase();
}
function render(model) {
  const h = model.header || {};
  const items = Array.isArray(model.items) ? model.items : [];
  const totalCurrent = items.reduce((sum, r) => sum + Number(r["Current Stock"] || 0), 0);
  const totalSuggested = items.reduce((sum, r) => sum + Number(r["Suggested Replenishment"] || 0), 0);
  const rows = items.map((r, index) => `
    <tr>
      <td>${index + 1}</td>
      <td>
        <div class="product-code">${esc(r["Product Code"])}</div>
        <div>${esc(r["Product Name"])}</div>
        <div class="small">${esc(r.Barcode || r.SKU || "")}</div>
      </td>
      <td>
        <div>${esc(r["Location Code"])}</div>
        <div class="small">${esc(r["Location Name"])}</div>
      </td>
      <td>${esc(r["Warehouse Code"])} - ${esc(r.Warehouse)}</td>
      <td class="right">${qty(r["Current Stock"])}</td>
      <td class="right">${qty(r["Minimum Quantity"])}</td>
      <td class="right">${qty(r["Maximum Quantity"])}</td>
      <td class="right">${qty(r["Sold Quantity"])}</td>
      <td class="right"><b>${qty(r["Suggested Replenishment"])}</b></td>
      <td class="center">
        <span class="priority ${priorityClass(r.Priority)}">${esc(r.Priority || "OK")}</span>
      </td>
      <td class="center"><span class="check-cell"></span></td>
    </tr>
  `).join("");
  document.getElementById("printRoot").innerHTML = `
    <div class="print-actions">
      <button class="print-btn" id="printBtn">Print</button>
    </div>

    <div class="print-page">
      <div class="header">
        <div class="company">
          ${h.companyLogoPath ? `<img class="logo" src="${esc(h.companyLogoPath)}">` : ""}
          <div>
            <div class="company-name">${esc(h.companyLegalName || h.companyName || "")}</div>
            <div class="muted">${esc(h.companyAddressLine1 || "")}</div>
            <div class="muted">${esc([h.companyPostalCode, h.companyCity, h.companyCountryCode].filter(Boolean).join(" "))}</div>
            <div class="muted">Tax No: ${esc(h.companyTaxNumber || "")}</div>
            <div class="muted">${esc(h.companyEmail || "")} ${esc(h.companyPhone || "")}</div>
          </div>
        </div>

        <div class="doc-title">
          <h1>Replenishment Report</h1>
          <div class="doc-number">${esc(h.periodLabel || "")}</div>
          <div class="status">${esc(h.reportDate || "")}</div>
        </div>
      </div>

      <div class="info-grid">
        <div class="info-box">
          <span>Warehouse</span>
          <b>${esc(h.warehouseCode || "All")} ${h.warehouseName ? "- " + esc(h.warehouseName) : ""}</b>
        </div>
        <div class="info-box">
          <span>Report Date</span>
          <b>${esc(h.reportDate || "")}</b>
        </div>
        <div class="info-box">
          <span>Printed By</span>
          <b>${esc(model.username || h.printedBy || "")}</b>
        </div>
      </div>

      <table class="report-table">
        <thead>
          <tr>
            <th>#</th>
            <th>Product</th>
            <th>Location</th>
            <th>Warehouse</th>
            <th class="right">Current</th>
            <th class="right">Min</th>
            <th class="right">Max</th>
            <th class="right">Sold</th>
            <th class="right">Refill</th>
            <th class="center">Priority</th>
            <th class="center">Done</th>
          </tr>
        </thead>
        <tbody>
          ${rows || `<tr><td colspan="11">No replenishment items found.</td></tr>`}
        </tbody>
      </table>

      <table class="summary">
        <tr><td>Total Lines</td><td class="right"><b>${items.length}</b></td></tr>
        <tr><td>Total Current Stock</td><td class="right"><b>${qty(totalCurrent)}</b></td></tr>
        <tr><td>Total Suggested Refill</td><td class="right"><b>${qty(totalSuggested)}</b></td></tr>
      </table>

      <div class="signatures">
        <div class="signature">Prepared by</div>
        <div class="signature">Completed by</div>
      </div>
    </div>
  `;
  document.getElementById("printBtn").onclick = function () {
    window.print();
  };
}
if (window.appsmith && appsmith.onReady) {
  appsmith.onReady(() => {
    render(appsmith.model || {});
  });
}
if (window.appsmith && appsmith.onModelChange) {
  appsmith.onModelChange(model => {
    render(model || {});
  });
}
setTimeout(() => {
  render(window.appsmith?.model || {});
}, 300);

